require_once '../config/db.php';if(session_status()===PHP_SESSION_NONE)session_start();if(!isset($_SESSION['user_id']))redirect('../index.php');$error='';
try{
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->beginTransaction();
 if(isset($_POST['add_loan'])){$accountId=(int)$_POST['account_id'];$type=in_array($_POST['loan_type'],['borrowed','lent'],true)?$_POST['loan_type']:'borrowed';$principal=round((float)$_POST['principal_amount'],2);if($principal<=0)throw new RuntimeException('Principal must be greater than zero.');$s=$pdo->prepare('INSERT INTO loans(account_id,lender_name,loan_type,principal_amount,outstanding_amount,annual_interest_rate,start_date,due_date,notes) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$accountId,trim((string)$_POST['lender_name']),$type,$principal,$principal,(float)$_POST['annual_interest_rate'],$_POST['start_date'],$_POST['due_date']?:null,trim((string)$_POST['notes'])]);$loanId=(int)$pdo->lastInsertId();$delta=$type==='borrowed'?$principal:-$principal;$pdo->prepare('UPDATE accounts SET current_balance=current_balance+? WHERE id=?')->execute([$delta,$accountId]);$s=$pdo->prepare('SELECT ledger_account_id FROM accounts WHERE id=?');$s->execute([$accountId]);$cash=(int)$s->fetchColumn()?: (int)$pdo->query("SELECT id FROM chart_of_accounts WHERE account_code='1000'")->fetchColumn();$other=(int)$pdo->query("SELECT id FROM chart_of_accounts WHERE account_code='".($type==='borrowed'?'2300':'1500')."'")->fetchColumn();$lines=$type==='borrowed'?[['account_id'=>$cash,'debit'=>$principal,'credit'=>0],['account_id'=>$other,'debit'=>0,'credit'=>$principal]]:[['account_id'=>$other,'debit'=>$principal,'credit'=>0],['account_id'=>$cash,'debit'=>0,'credit'=>$principal]];post_journal($pdo,$_POST['start_date'],'LOAN-'.$loanId,ucfirst($type).' loan: '.trim((string)$_POST['lender_name']),$lines,'loan',$loanId);
 }elseif(isset($_POST['loan_payment'])){$loanId=(int)$_POST['loan_id'];$s=$pdo->prepare('SELECT * FROM loans WHERE id=? FOR UPDATE');$s->execute([$loanId]);$loan=$s->fetch();$amount=round((float)$_POST['amount'],2);$interest=round((float)$_POST['interest_component'],2);$principal=round($amount-$interest,2);if(!$loan||$amount<=0||$principal<=0||$principal>$loan['outstanding_amount'])throw new RuntimeException('Invalid repayment allocation.');$accountId=(int)$_POST['account_id'];$pdo->prepare('INSERT INTO loan_payments(loan_id,account_id,payment_date,amount,principal_component,interest_component,notes) VALUES(?,?,?,?,?,?,?)')->execute([$loanId,$accountId,$_POST['payment_date'],$amount,$principal,$interest,trim((string)$_POST['notes'])]);$newOutstanding=round($loan['outstanding_amount']-$principal,2);$pdo->prepare('UPDATE loans SET outstanding_amount=?,status=? WHERE id=?')->execute([$newOutstanding,$newOutstanding<=0?'settled':'active',$loanId]);$delta=$loan['loan_type']==='borrowed'?-$amount:$amount;$pdo->prepare('UPDATE accounts SET current_balance=current_balance+? WHERE id=?')->execute([$delta,$accountId]);
 }
 $pdo->commit();redirect('loans.php?saved=1');}}
catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
$accounts=$pdo->query('SELECT id,account_name,current_balance FROM accounts WHERE is_active=1 ORDER BY account_name')->fetchAll();$loans=$pdo->query("SELECT l.*,a.account_name,COALESCE((SELECT SUM(lp.amount) FROM loan_payments lp WHERE lp.loan_id=l.id),0) total_paid FROM loans l JOIN accounts a ON a.id=l.account_id ORDER BY l.created_at DESC")->fetchAll();$borrowed=(float)$pdo->query("SELECT COALESCE(SUM(outstanding_amount),0) FROM loans WHERE loan_type='borrowed' AND status='active'")->fetchColumn();$lent=(float)$pdo->query("SELECT COALESCE(SUM(outstanding_amount),0) FROM loans WHERE loan_type='lent' AND status='active'")->fetchColumn();require_once 'includes/header.php';require_once 'includes/sidebar.php';
