<main class="flex-1 h-screen overflow-y-auto app-scroll"><header class="bg-white border-b px-5 md:px-8 py-5 flex items-center gap-4 sticky top-0 z-10"><button data-sidebar-toggle class="lg:hidden text-2xl">☰</button><div><h2 class="text-2xl font-bold">Loans</h2><p class="text-sm text-slate-500">Track borrowed and lent funds, interest, and repayments</p></div></header><div class="p-5 md:p-8 max-w-7xl mx-auto"><?php if(isset($_GET['saved'])):?><div class="bg-emerald-50 border p-4 rounded-xl mb-5">Loan record updated.</div><?php endif;?><?php if($error):?><div class="bg-rose-50 text-rose-800 border p-4 rounded-xl mb-5"><?=h($error)?></div><?php endif;?><div class="grid sm:grid-cols-2 gap-4 mb-6"><div class="bg-white border rounded-xl p-5"><p class="text-sm text-slate-500">We owe</p><p class="text-2xl font-black text-rose-700"><?=money($pdo,$borrowed)?></p></div><div class="bg-white border rounded-xl p-5"><p class="text-sm text-slate-500">Owed to us</p><p class="text-2xl font-black text-emerald-700"><?=money($pdo,$lent)?></p></div></div>
