ils><?php endif;?></article><?php endforeach;?><?php if(!$loans):?><div class="bg-white border rounded-2xl p-12 text-center text-slate-500">No loans recorded.</div><?php endif;?></section></div></div></main><?php require_once 'includes/footer.php';?>
